package br.com.onda;
import android.content.Context;import android.net.Uri;import android.util.AtomicFile;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
/** Private plan plus append-only per-file results. A torn final log line is ignored after a crash. */
@androidx.media3.common.util.UnstableApi
final class ChapterBatchStore {
 static final class Result{final int index;final String title,error;final Uri uri;Result(int index,String title,Uri uri,String error){this.index=index;this.title=title;this.uri=uri;this.error=error;}}
 private static File file(Context c,String token,String extension)throws IOException{if(token==null||!token.matches("[a-f0-9-]{36}"))throw new IOException("Pedido inválido");File dir=new File(c.getFilesDir(),"chapter-batches");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("Não foi possível guardar o pedido");return new File(dir,token+extension);}
 static void save(Context c,ChapterBatchPlan plan)throws IOException{try{byte[] bytes=plan.json().toString().getBytes(StandardCharsets.UTF_8);AtomicFile target=new AtomicFile(file(c,plan.token,".json"));FileOutputStream out=target.startWrite();try{out.write(bytes);target.finishWrite(out);}catch(IOException|RuntimeException error){target.failWrite(out);throw error;}}catch(JSONException error){throw new IOException(error);}}
 static ChapterBatchPlan load(Context c,String token)throws IOException{AtomicFile target=new AtomicFile(file(c,token,".json"));try(InputStream in=target.openRead();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>4*1024*1024)throw new IOException("Seleção inválida");out.write(buffer,0,n);}return ChapterBatchPlan.parse(out.toString("UTF-8"));}}
 static synchronized void append(Context c,String token,ChapterBatchPlan.Row row,Uri uri,String error)throws IOException{try{String line=new JSONObject().put("index",row.index).put("title",row.title).put("uri",uri==null?JSONObject.NULL:uri.toString()).put("error",error==null?"":error).toString()+"\n";try(FileOutputStream out=new FileOutputStream(file(c,token,".jsonl"),true)){out.write(line.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}}catch(JSONException e){throw new IOException(e);}}
 static void discardEmpty(Context c,Uri source,Uri target){if(target==null||target.equals(source))return;try(android.content.res.AssetFileDescriptor original=c.getContentResolver().openAssetFileDescriptor(source,"r");android.content.res.AssetFileDescriptor output=c.getContentResolver().openAssetFileDescriptor(target,"r")){if(original==null||output==null)return;android.system.StructStat a=android.system.Os.fstat(original.getFileDescriptor()),b=android.system.Os.fstat(output.getFileDescriptor());if(b.st_size==0&&!(a.st_dev==b.st_dev&&a.st_ino==b.st_ino))android.provider.DocumentsContract.deleteDocument(c.getContentResolver(),target);}catch(Exception ignored){}}
 static synchronized List<Result> results(Context c,String token)throws IOException{ArrayList<Result> results=new ArrayList<>();File file=file(c,token,".jsonl");if(!file.isFile())return results;try(BufferedReader reader=new BufferedReader(new InputStreamReader(new FileInputStream(file),StandardCharsets.UTF_8))){String line;while((line=reader.readLine())!=null){try{JSONObject j=new JSONObject(line);String value=j.isNull("uri")?null:j.getString("uri");results.add(new Result(j.getInt("index"),j.getString("title"),value==null?null:Uri.parse(value),j.getString("error")));}catch(JSONException ignored){/* Only a complete committed result is offered for opening/sharing. */}}}return results;}
}
